"{n}nd phase (SOW V{n}): direct API integration with payer or regulator e-claim portals, automated ERA parsing, AI-assisted pre-authorization and denial prediction, denial analytics dashboard, coding management, additional authority rule sets.": "المرحلة {n} (SOW V{n}): التكامل المباشر عبر API مع بوابات المطالبات الإلكترونية للجهات الدافعة أو الجهات التنظيمية، والتحليل الآلي لإشعارات السداد (ERA)، والموافقة المسبقة بمساعدة الذكاء الاصطناعي والتنبؤ بالرفض، ولوحة تحليلات الرفض، وإدارة الترميز، ومجموعات قواعد إضافية للجهات.",
"{n}nd phase masters, not configured here: Discount and Concession Matrix, Billing Counter and Till, Receipt and Invoice Series. The VAT masters in the {n}nd phase list overlap with the Tax and VAT master below (confirmation required).": "بيانات المرحلة {n} الرئيسية غير المضبوطة هنا: مصفوفة الخصومات والتنازلات، ومكتب الفوترة والصندوق، وسلاسل الإيصالات والفواتير. تتداخل بيانات ضريبة القيمة المضافة في قائمة المرحلة {n} مع البيانات الرئيسية للضرائب وضريبة القيمة المضافة أدناه (يلزم التأكيد).",
"{n}nd phase: PACS integration": "المرحلة {n}: تكامل PACS",
